WITH base AS (SELECT id, dept_id, manager_id, salary, hire_date, is_remote, level, CAST(salary AS INT) AS salary_int FROM employees WHERE job_title IS NOT NULL AND NOT is_remote), filtered AS (SELECT id, dept_id, manager_id, salary, hire_date, level, salary_int, salary_int - salary AS salary_int_minus_salary FROM base WHERE hire_date > DATE '2023-03-28' AND hire_date >= '2025-03-01'), scored AS (SELECT *, COUNT(salary_int_minus_salary) OVER (PARTITION BY manager_id ORDER BY salary_int_minus_salary, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_count_salary_int_minus_salary, SUM(salary_int_minus_salary) OVER (PARTITION BY manager_id ORDER BY salary_int_minus_salary, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_sum_salary_int_minus_salary, AVG(salary_int_minus_salary) OVER (PARTITION BY manager_id ORDER BY salary_int_minus_salary, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_avg_salary_int_minus_salary, PERCENT_RANK() OVER (PARTITION BY dept_id ORDER BY salary_int_minus_salary DESC) AS salary_int_minus_salary_percent_rank FROM filtered), base_employees AS (SELECT *, CEIL(salary_int_minus_salary_percent_rank) AS salary_int_minus_salary_percent_rank_whole FROM scored WHERE hire_date > DATE '2023-02-19' AND manager_id IS NOT NULL), latest AS (SELECT * FROM base_employees QUALIFY ROW_NUMBER() OVER (PARTITION BY level, manager_id ORDER BY last4_sum_salary_int_minus_salary DESC, id) = 1), scored_employees AS (SELECT *, AVG(salary) OVER w_hist AS salary_avg_3_prior, SUM(salary) OVER (PARTITION BY level ORDER BY salary_int, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_salary, LEAD(last4_sum_salary_int_minus_salary, 1, 0) OVER (PARTITION BY level ORDER BY salary_int_minus_salary_percent_rank, id) AS next_last4_sum_salary_int_minus_salary FROM latest WHERE manager_id IN (26, 29, 36) WINDOW w_hist AS (PARTITION BY dept_id ORDER BY salary_int_minus_salary_percent_rank, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING)) SELECT id, dept_id, manager_id, salary, hire_date, salary_int, last4_count_salary_int_minus_salary, last4_sum_salary_int_minus_salary, salary_int_minus_salary_percent_rank FROM scored_employees;
